head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = "";

///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
/**
 * @method
 * @name onpageload
 * @description 화면이 최초 로드될때 실행되는 초기화 이벤트 (현재 처리 없음 — 초기화는 gform_onload 에서 수행)
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트 (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_ExportDmstCompstDrft1_OnLoadError
 * @description dts_ExportDmstCompstDrft1 로드 오류 콜백 — 오류 내용을 알림으로 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dts_ExportDmstCompstDrft1_OnLoadError();
 */
scwin.dts_ExportDmstCompstDrft1_OnLoadError = function() {
    try {
        $c.win.alert(dts_ExportDmstCompstDrft1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00221.dts_ExportDmstCompstDrft1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ExportDmstCompstDrft1_OnLoadCompleted
 * @description dts_ExportDmstCompstDrft1 로드 완료 콜백 — 오류 메시지 확인 후 그리드 타이틀을 세팅한다.
 * @param {Number} rowcount 로드된 행 수
 * @returns {void}
 * @hidden N
 * @example scwin.dts_ExportDmstCompstDrft1_OnLoadCompleted(dts_ExportDmstCompstDrft1.getRowCount());
 */
scwin.dts_ExportDmstCompstDrft1_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_ExportDmstCompstDrft1.errorMsg) {
            alert(dts_ExportDmstCompstDrft1.errorMsg);
            return;
        }
        // 그리드 타이틀 세팅.
        scwin.setGrdTitle();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00221.dts_ExportDmstCompstDrft1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ExportDmstCompstDrft2_OnLoadError
 * @description dts_ExportDmstCompstDrft2 로드 오류 콜백 — 오류 내용을 알림으로 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dts_ExportDmstCompstDrft2_OnLoadError();
 */
scwin.dts_ExportDmstCompstDrft2_OnLoadError = function() {
    try {
        $c.win.alert(dts_ExportDmstCompstDrft2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00221.dts_ExportDmstCompstDrft2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ExportDmstCompstDrft2_OnLoadCompleted
 * @description dts_ExportDmstCompstDrft2 로드 완료 콜백 — 오류 메시지를 확인한다.
 * @param {Number} rowcount 로드된 행 수
 * @returns {void}
 * @hidden N
 * @example scwin.dts_ExportDmstCompstDrft2_OnLoadCompleted(dts_ExportDmstCompstDrft2.getRowCount());
 */
scwin.dts_ExportDmstCompstDrft2_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_ExportDmstCompstDrft2.errorMsg) {
            alert(dts_ExportDmstCompstDrft2.errorMsg);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00221.dts_ExportDmstCompstDrft2_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchStdDt
 * @description 최근 3년 결산일자 조회
 * @returns {void}
 * @hidden N
 * @example await scwin.searchStdDt();
 */
scwin.searchStdDt = async function() {
    const sbmOptions = {
        id : "sbm_dts_ExportDmstCompstDrft1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ExportDmstCompstDrft1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_ExportDmstCompstDrft1_OnLoadCompleted(dts_ExportDmstCompstDrft1.getRowCount()); // 구 콜백 연결

};

/**
 * @method
 * @name searchExportDmstCompstDrft
 * @description 수출및내수구성추이 조회
 * @returns {void}
 * @hidden N
 * @example await scwin.searchExportDmstCompstDrft();
 */
scwin.searchExportDmstCompstDrft = async function() {
    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_ExportDmstCompstDrft2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ExportDmstCompstDrft2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_ExportDmstCompstDrft2_OnLoadCompleted(dts_ExportDmstCompstDrft2.getRowCount()); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
// 조회조건 결산일자

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {void}
 * @hidden N
 * @example scwin.init();
 */
scwin.init = function() {
    // 결산일자 조회

    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 * @example scwin.initDs();
 */
scwin.initDs = function() {
    dts_ExportDmstCompstDrft1.removeAll();
    dts_ExportDmstCompstDrft2.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Boolean} 조회조건이 유효하면 true, 아니면 false
 * @hidden N
 * @example scwin.chkValid();
 */
scwin.chkValid = function() {
    // 필수항목 체크.

    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description 수출및내수구성추이 조회
 * @returns {void}
 * @hidden N
 * @example scwin.search();
 */
scwin.search = function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시

    // 최근 3년 결산일자 조회
    scwin.searchStdDt();
};

/**
 * @method
 * @name setGrdTitle
 * @description 그리드 타이틀 세팅.
 * @returns {void}
 * @hidden N
 * @example scwin.setGrdTitle();
 */
scwin.setGrdTitle = function() {
    $c.cm.setColumnProp(grd_ExportDmstCompstDrft, "YYYYMMDD1", "Name", $c.stf.FormatDateEx(dts_ExportDmstCompstDrft1.getCellData(1, "STD_DT")));
    $c.cm.setColumnProp(grd_ExportDmstCompstDrft, "YYYYMMDD2", "Name", $c.stf.FormatDateEx(dts_ExportDmstCompstDrft1.getCellData(2, "STD_DT")));
    $c.cm.setColumnProp(grd_ExportDmstCompstDrft, "YYYYMMDD3", "Name", $c.stf.FormatDateEx(dts_ExportDmstCompstDrft1.getCellData(3, "STD_DT")));

    // 수출및내수구성추이 조회
    scwin.searchExportDmstCompstDrft();
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {void}
 * @hidden N
 * @example scwin.excelDownload();
 */
scwin.excelDownload = function() {
    if (dts_ExportDmstCompstDrft2.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_ExportDmstCompstDrft, {fileName: "수출및내수구성추이", type: "8"});
};

/**
 * @method
 * @name gform_onload
 * @description (구) 폼 로드 핸들러 — 화면 초기화(init)를 호출한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = function() {
    scwin.init();
};
